// A display snapshot only. Bounty transactions always re-read the live target.
import { CHAIN, CONTRACTS } from './chain-config.js';

export const RECORDS_REFRESH_MS = 30 * 60_000;
const CACHE_KEY = `degenerus:records:v1:${CHAIN.id}:${CONTRACTS.GAME}:${CONTRACTS.COINFLIP}:${CONTRACTS.CRAPS}`.toLowerCase();

function validState(state) {
  return typeof state?.recordPoolWei === 'bigint' && state.recordPoolWei >= 0n
    && Array.isArray(state.records) && state.records.length === 5
    && state.records.every((record, kind) => record?.kind === kind
      && record.meta?.kind === kind
      && typeof record.value === 'bigint' && record.value >= 0n
      && typeof record.barToBeat === 'bigint'
      && typeof record.totalPaidFlip === 'bigint'
      && typeof record.meta.floorValue === 'bigint');
}

export function readRecordsCache(now = Date.now()) {
  try {
    const cached = JSON.parse(localStorage.getItem(CACHE_KEY), (_key, value) => (
      value && typeof value === 'object' && Object.keys(value).length === 1 && typeof value.bigint === 'string'
        ? BigInt(value.bigint) : value
    ));
    if (!Number.isSafeInteger(cached?.savedAt) || cached.savedAt <= 0 || cached.savedAt > now
      || !validState(cached.state)) return null;
    if (cached.profiles != null) cached.profiles = Array.isArray(cached.profiles)
      ? cached.profiles.filter(row => Array.isArray(row) && row.length === 2
        && /^0x[0-9a-f]{40}$/i.test(row[0]) && typeof row[1]?.name === 'string') : [];
    // Even an expired snapshot can paint immediately while refresh runs.
    return cached;
  } catch (_) { return null; }
}

export function writeRecordsCache(state, savedAt = Date.now(), profiles = null) {
  if (!validState(state)) return;
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify({ state, savedAt, ...(profiles instanceof Map ? { profiles: [...profiles] } : {}) }, (_key, value) => (
      typeof value === 'bigint' ? { bigint: String(value) } : value
    )));
  } catch (_) { /* Storage may be blocked or full; the mounted snapshot survives. */ }
}
